-- One-off import of Exercise.pdf into the exercise tables (generated by import/build.py; do not edit by hand).
-- Owner: lacche96@gmail.com.  56 sessions, 921 sets, 26 exercises.
-- Run once in the Supabase SQL editor, after schema.sql, functions.sql and grants.sql.
-- It runs as one transaction: any failed check raises an error and nothing is written.
-- The editor has no signed-in user (auth.uid() is NULL), so user_id and created_by are written explicitly.
-- Exercises that already exist by name are reused. If the owner already has a session on any of
-- these dates the script stops before changing anything.

begin;

create temporary table imp_user (id uuid not null) on commit drop;
insert into imp_user select id from auth.users where email = 'lacche96@gmail.com';

do $$
begin
  if (select count(*) from imp_user) <> 1 then
    raise exception 'user lacche96@gmail.com not found in auth.users';
  end if;
  if not exists (select 1 from public.hub_profiles p join imp_user u on u.id = p.user_id) then
    raise exception 'no hub_profiles row for lacche96@gmail.com: run schema.sql first';
  end if;
  if exists (
    select 1 from public.exercise_sessions s join imp_user u on u.id = s.user_id
    where s.entry_date in ('2025-11-21'::date, '2025-11-22'::date, '2025-11-24'::date, '2025-11-28'::date, '2025-12-01'::date, '2025-12-02'::date, '2025-12-11'::date, '2025-12-22'::date, '2025-12-24'::date, '2025-12-26'::date, '2025-12-27'::date, '2025-12-29'::date, '2025-12-30'::date, '2026-01-05'::date, '2026-01-09'::date, '2026-01-12'::date, '2026-01-16'::date, '2026-01-19'::date, '2026-01-22'::date, '2026-01-28'::date, '2026-01-31'::date, '2026-02-05'::date, '2026-02-09'::date, '2026-02-17'::date, '2026-02-19'::date, '2026-02-23'::date, '2026-02-24'::date, '2026-02-26'::date, '2026-03-06'::date, '2026-03-07'::date, '2026-03-09'::date, '2026-03-10'::date, '2026-03-12'::date, '2026-03-13'::date, '2026-03-14'::date, '2026-03-16'::date, '2026-03-19'::date, '2026-03-23'::date, '2026-03-24'::date, '2026-03-26'::date, '2026-03-27'::date, '2026-03-30'::date, '2026-04-02'::date, '2026-04-03'::date, '2026-04-06'::date, '2026-04-07'::date, '2026-04-09'::date, '2026-04-10'::date, '2026-04-13'::date, '2026-04-14'::date, '2026-04-16'::date, '2026-04-18'::date, '2026-04-21'::date, '2026-04-23'::date, '2026-04-24'::date, '2026-04-30'::date)
