-- 2. Families: variants point at their base exercise
update public.exercise_catalog c set parent_id = p.id
from (values
  ('deadlift dumbbell stiff legged', 'deadlift dumbbell'),
  ('fly dumbbell rear delt', 'fly dumbbell'),
  ('press dumbbell close grip', 'press dumbbell'),
  ('press dumbbell reverse grip', 'press dumbbell'),
  ('press dumbbell military', 'press dumbbell'),
  ('plank side', 'plank')
) as f(child, parent)
join public.exercise_catalog p on p.name_en = f.parent
where c.name_en = f.child and c.parent_id is null;

